'use strict';
// First-run helper: node scripts/init.js  (or: npm run init)
// Creates .env with freshly generated secrets. Refuses to overwrite an existing .env,
// because losing SENDERBOLT_MASTER_KEY makes stored sender passwords unrecoverable.
var fs = require('fs');
var path = require('path');
var crypto = require('crypto');

var target = path.join(process.cwd(), '.env');
if (fs.existsSync(target)) {
  console.log('.env already exists - leaving it untouched.');
  process.exit(0);
}
var lines = [
  '# Generated by scripts/init.js. NEVER commit this file. BACK UP SENDERBOLT_MASTER_KEY somewhere safe:',
  '# without it, saved sender app passwords cannot be decrypted.',
  'SENDERBOLT_MASTER_KEY=' + crypto.randomBytes(32).toString('hex'),
  'SENDERBOLT_SESSION_SECRET=' + crypto.randomBytes(32).toString('hex'),
  '# Optional: required when creating the first account (recommended if not on localhost).',
  'SENDERBOLT_SETUP_TOKEN=' + crypto.randomBytes(16).toString('hex'),
  '# Sending engine: off | dry-run (nothing real is sent) | live (real SMTP + IMAP).',
  'SENDERBOLT_SENDING=dry-run',
  'HOST=127.0.0.1',
  'PORT=3000',
  ''
];
fs.writeFileSync(target, lines.join('\n'), { mode: 384 });   // 0600
console.log('Created .env with new secrets.');
console.log('Open it, copy SENDERBOLT_SETUP_TOKEN (needed once, when creating your account),');
console.log('and back up SENDERBOLT_MASTER_KEY.');
